Створено новий Flutter-проєкт за допомогою команди: flutter create task_manager --org com.taskmaster --project-name task_manager. Відповідно до вимог варіанту, назва проєкту task_manager записана у нижньому регістрі з нижнім підкресленням. Досліджено призначення ключових каталогів застосунку:
• android/ — містить специфічний код для Android, маніфест AndroidManifest.xml та конфігурації Gradle (build.gradle.kts);
• ios/ — каталог з нативним проєктом для Apple iOS та файлами конфігурації Xcode;
• windows/ та web/ — конфігурації для збірки нативних настільних (C++) та веб-застосунків;
• lib/ — основний робочий каталог із вихідним кодом мовою Dart (точка входу main.dart);
• test/ — модульні та віджет-тести для автоматизованої перевірки працездатності;
• pubspec.yaml — конфігураційний файл пакета: назва, версія, зовнішні залежності, шрифти та асети.

import 'package:flutter/material.dart';

void main() {
  runApp(const TaskManagerApp());
}

class TaskManagerApp extends StatelessWidget {
  const TaskManagerApp({super.key});
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Менеджер завдань',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFFD4FF00),
          brightness: Brightness.dark,
          primary: const Color(0xFFD4FF00),
          surface: const Color(0xFF15181F),
        ),
        scaffoldBackgroundColor: const Color(0xFF0D0F13),
      ),
      home: const TaskManagerHomePage(title: 'Менеджер завдань'),
    );
  }
}

class TaskItem {
  final String title;
  final String category;
  bool isCompleted;
  TaskItem({required this.title, required this.category, this.isCompleted = false});
}

class TaskManagerHomePage extends StatefulWidget {
  final String title;
  const TaskManagerHomePage({super.key, required this.title});
  @override
  State<TaskManagerHomePage> createState() => _TaskManagerHomePageState();
}

class _TaskManagerHomePageState extends State<TaskManagerHomePage> {
  final List<TaskItem> _tasks = [
    TaskItem(title: 'Встановити Android Studio та Flutter SDK', category: 'Навчання', isCompleted: true),
    TaskItem(title: 'Налаштувати емулятор Android', category: 'Навчання', isCompleted: true),
    TaskItem(title: 'Створити Flutter-проєкт для Варіанту 1', category: 'ПМД Лаб 1', isCompleted: true),
    TaskItem(title: 'Оформити звіт з лабораторної роботи №1', category: 'ПМД Лаб 1', isCompleted: false),
  ];
  final TextEditingController _taskController = TextEditingController();
  int get _completedCount => _tasks.where((t) => t.isCompleted).length;

  void _toggleTask(int index) {
    setState(() { _tasks[index].isCompleted = !_tasks[index].isCompleted; });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(widget.title), centerTitle: true),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Text('Варіант 1: Менеджер завдань ($_completedCount / ${_tasks.length})'),
            Expanded(
              child: ListView.builder(
                itemCount: _tasks.length,
                itemBuilder: (context, i) => Card(
                  child: ListTile(
                    leading: Checkbox(value: _tasks[i].isCompleted, onChanged: (_) => _toggleTask(i)),
                    title: Text(_tasks[i].title),
                    subtitle: Text(_tasks[i].category),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
